<?php
declare(strict_types=1);
namespace App\Services;
final class ModuleAttachmentClient { public function __construct(private readonly ModuleEndpointPolicy $policy,private readonly int $timeout=5,private readonly int $maxBytes=262144,private readonly mixed $transport=null){}public function request(string $endpoint,array $body):array{$endpoint=$this->policy->assertAllowed($endpoint);if(is_callable($this->transport))return ($this->transport)($endpoint,$body,$this->timeout,$this->maxBytes);$this->policy->assertPublicResolution($endpoint);if(!function_exists('curl_init'))throw new ModuleAttachmentException('transport_unavailable','Não foi possível localizar o módulo.');$payload=json_encode($body,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$received='';$type='';$tooLarge=false;$curl=curl_init($endpoint);curl_setopt_array($curl,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Accept: application/json'],CURLOPT_RETURNTRANSFER=>false,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>$this->timeout,CURLOPT_TIMEOUT=>$this->timeout,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_REDIR_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_HEADERFUNCTION=>static function($ch,$line)use(&$type){if(stripos($line,'Content-Type:')===0)$type=trim(substr($line,13));return strlen($line);},CURLOPT_WRITEFUNCTION=>function($ch,$chunk)use(&$received,&$tooLarge){if(strlen($received)+strlen($chunk)>$this->maxBytes){$tooLarge=true;return 0;}$received.=$chunk;return strlen($chunk);}]);$ok=curl_exec($curl);$status=(int)curl_getinfo($curl,CURLINFO_RESPONSE_CODE);$errno=curl_errno($curl);curl_close($curl);if($tooLarge)throw new ModuleAttachmentException('response_too_large','A resposta do módulo é incompatível.');if(!$ok||$errno||$status<200||$status>=300)throw new ModuleAttachmentException($errno===CURLE_OPERATION_TIMEDOUT?'timeout':'module_unavailable',$errno===CURLE_OPERATION_TIMEDOUT?'O módulo não respondeu dentro do prazo.':'Não foi possível localizar o módulo.');if(!str_starts_with(strtolower($type),'application/json'))throw new ModuleAttachmentException('invalid_content_type','A resposta do módulo é incompatível.');try{$decoded=json_decode($received,true,32,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new ModuleAttachmentException('invalid_json','A resposta do módulo é incompatível.');}if(!is_array($decoded))throw new ModuleAttachmentException('invalid_json','A resposta do módulo é incompatível.');return $decoded;} }
